/** Package the exact content-script bytes exercised by browser tests.
 * No runtime func serialisation or bundler-captured closures on the page boundary.
 */
import {readFile,writeFile,mkdir} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const parts=[];
for(const file of ['../../protocol/src/reply-json','message-wire','chat-dom','page-endpoint']){
 let text=await readFile(path.join(root,'dist/packages/bridge/src',file+'.js'),'utf8');
 text=text.replace(/^import \{[^}]+\} from '\.\.\/\.\.\/protocol\/src\/reply-json\.js';\s*/gm,'').replace(/^import \{[^}]+\} from '\.\/(?:chat-dom|message-wire)\.js';\s*/gm,'').replace(/^export /gm,'').replace(/^\/\/# sourceMappingURL=.*$/gm,'');
 if(/^\s*(?:import |export )/m.test(text))throw new Error(`Unexpected module in page bundle: ${file}`);
 parts.push(text);
}
const output='/* Generated by scripts/build-page.mjs. Source: packages/bridge/src. */\n(()=>{\n"use strict";\n'+parts.join('\n')+'\ninstallPageEndpoint(chrome.runtime);\n})();\n';
const target=path.join(root,'apps/extension/public/mitter-page.js');
await mkdir(path.dirname(target),{recursive:true});await writeFile(target,output);
console.log('Packaged persistent page bridge ('+Buffer.byteLength(output)+' bytes).');
